# Device grid-dimension limit (Ascend coreDim <= 65535).
_MAX_GRID_X = 65535
# Largest flat offset (in elements) we allow before falling back to int64 math.
_INT32_LIMIT = 2**31
# Elements handled by a single program in the specialised last-dim kernel.
_ROW_BLOCK = 2048
_MIN_ROW_BLOCK = 64
# Sort-based last-dim path: widest UB tile (elements), the exact-integer range
# of float32 (sort keys are packed ints held in fp32 so that ``tl.gather`` can
# move them around), and bounds on the unrolled destination blocks / source
# chunks per row.
_SORT_TILE = 2048
_FP32_EXACT = 2**24
_SORT_MAX_BLOCKS = 2
_SORT_MAX_CHUNKS = 4
# ``tl.gather`` on this backend only accepts float / fp8 / int8 payloads.
_SORT_DTYPES = (torch.float16, torch.float32, torch.bfloat16)


@triton.jit(do_not_specialize=["n"])
def _copy_flat_kernel(src_ptr, dst_ptr, n, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    step = tl.num_programs(0)
    for blk in range(pid, tl.cdiv(n, BLOCK), step):
        off = blk * BLOCK + tl.arange(0, BLOCK)
        mask = off < n
        tl.store(dst_ptr + off, tl.load(src_ptr + off, mask=mask), mask=mask)


def _clone_contiguous(x):
    """``x.clone()`` for a contiguous tensor with a grid-bounded copy.

    The generic clone kernel launches ``cdiv(n, 1024)`` programs directly, so
    tensors wider than ``65535 * 1024`` elements are refused by the driver
    (``coreDim`` overflow).  The benchmark inputs (e.g. 1024x65536) hit that.
    """
    out = torch.empty_like(x)
    n = x.numel()
    if n == 0:
        return out
    grid = (min(triton.cdiv(n, 8192), _MAX_GRID_X),)
    _copy_flat_kernel[grid](x, out, n, BLOCK=8192)
    return out


@libentry()
@triton.jit(
    do_not_specialize=[
        "C",
        "out_stride",
        "src_stride",
        "tiles_per_row",
        "n_tiles",
    ]
)
def _scatter_last_dim_kernel(
    src,
    index,
    out,
    C,
    out_stride,
    src_stride,
    tiles_per_row,
    n_tiles,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
):
    """Scatter where ``dim`` is the innermost dimension of contiguous tensors.

    Every index/src/out row is contiguous, so a program owns one
    ``(row, BLOCK)`` tile.  Loads stay affine (vector loads); only the final
    store is scattered.  The grid is capped and walked with a stride loop.
    """
    pid = tl.program_id(0)
    step = tl.num_programs(0)
    cols = tl.arange(0, BLOCK)
    for tile in range(pid, n_tiles, step):
        row = tile // tiles_per_row
        col = (tile - row * tiles_per_row) * BLOCK
        if EVEN:
            cur_index = tl.load(index + row * C + col + cols).to(tl.int32)
            cur_src = tl.load(src + row * src_stride + col + cols)
            tl.store(out + row * out_stride + cur_index, cur_src)
        else:
            mask = col + cols < C
            cur_index = tl.load(index + row * C + col + cols, mask=mask, other=0).to(
                tl.int32
            )
            cur_src = tl.load(src + row * src_stride + col + cols, mask=mask, other=0)
            tl.store(out + row * out_stride + cur_index, cur_src, mask=mask)


def _next_pow2(n: int) -> int:
    return 1 << (n - 1).bit_length()


@triton.jit
def _scatter_search_block(
    key,
    sorted_src,
    t1,
    dst,
    out_cols: tl.constexpr,
    acc,
    S: tl.constexpr,
    LOGS: tl.constexpr,
):
    """Resolve one destination block against a sorted source chunk on-chip.

    ``key`` holds the sorted packed keys, ``t1`` the packed key of this lane's
    destination (``dst * S``).  A binary search locates the run start and its
    value (if the run exists in this chunk) overwrites ``acc``.
    """
    lo = tl.zeros([S], tl.int32)
    hi = tl.zeros([S], tl.int32) + S
    for _ in tl.static_range(LOGS + 1):
        mid = tl.minimum((lo + hi) >> 1, S - 1)
        go = (tl.gather(key, mid, axis=0) < t1) & (lo < hi)
        lo = tl.where(go, mid + 1, lo)
        hi = tl.where(go, hi, tl.minimum(mid, hi))
    ls = tl.minimum(lo, S - 1)
    found = tl.gather(key, ls, axis=0)
    hit = (lo < S) & (found >= t1) & (found < t1 + S) & (dst < out_cols)
    return tl.where(hit, tl.gather(sorted_src, ls, axis=0), acc)


@triton.jit(do_not_specialize=["rows"])
def _scatter_last_dim_sort_kernel(
    src,
    index,
    out,
    rows,
    src_cols: tl.constexpr,
    src_row_stride: tl.constexpr,
    out_cols: tl.constexpr,
    S: tl.constexpr,
    LOGS: tl.constexpr,
    NBLK: tl.constexpr,
):
    """Scatter along the innermost dim without a single scattered store.

    A naive ``tl.store(out + idx, val)`` lowers to one scalar DMA per element
    (~3.2 ns/element on this backend).  Instead every program owns a row and
    turns the scatter into a *dense* write:

    1. Pack each source element into one exactly-representable fp32 key
       ``idx * S + (S - 1 - lane)`` -- the reversed lane makes the *last*
       duplicate sort first, matching torch's last-write-wins order.
    2. ``extension.sort`` the chunk on-chip, then gather the payload into the
       sorted order (all on-chip ``tl.gather``s are cheap; a data-dependent
       *global* load is not).
    3. For each destination, binary-search the sorted chunk on-chip for its
       run and keep the value; later chunks simply overwrite earlier ones.

    Writes are therefore fully contiguous and no atomics are involved.  The
    tile is capped at ``_SORT_TILE``; sources are walked in chunks (one sort
    each) and a small, unrolled set of destination blocks shares that sort.
    """
    pid = tl.program_id(0)
    step = tl.num_programs(0)
    off = tl.arange(0, S)
    tconst = off * S
    # Placeholder so the second block's accumulator is typed like ``out`` even
    # when ``NBLK == 1`` (the branch below is resolved statically).
    acc1 = tl.zeros([S], dtype=out.dtype.element_ty)
    for row in range(pid, rows, step):
        dst0 = off
        dst1 = S + off
        acc0 = tl.load(out + row * out_cols + dst0, mask=dst0 < out_cols, other=0)
        if NBLK > 1:
            acc1 = tl.load(out + row * out_cols + dst1, mask=dst1 < out_cols, other=0)
        for c0 in range(0, src_cols, S):
            so = c0 + off
            live = so < src_cols
            # ``other=out_cols`` parks padding lanes past every real key.
            cur_index = tl.load(
                index + row * src_cols + so, mask=live, other=out_cols
            ).to(tl.int32)
            key = _al.sort((cur_index * S + (S - 1 - off)).to(tl.float32), dim=-1)
            src_lane = tl.minimum(S - 1 - (key.to(tl.int32) & (S - 1)), S - 1)
            cur_src = tl.load(src + row * src_row_stride + so, mask=live, other=0)
            sorted_src = tl.gather(cur_src, src_lane, axis=0)
            acc0 = _scatter_search_block(
                key, sorted_src, tconst, dst0, out_cols, acc0, S=S, LOGS=LOGS
            )
            if NBLK > 1:
                acc1 = _scatter_search_block(
                    key,
                    sorted_src,
                    tconst + S * S,
                    dst1,
                    out_cols,
                    acc1,
                    S=S,
                    LOGS=LOGS,
                )
        tl.store(out + row * out_cols + dst0, acc0, mask=dst0 < out_cols)
        if NBLK > 1:
            tl.store(out + row * out_cols + dst1, acc1, mask=dst1 < out_cols)


def _scatter_last_dim_sorted(out, dim, index, src) -> bool:
    """Sort-based last-dim scatter; returns False when the shape does not fit.

    The destination side must be coverable with a small, unrolled number of
    blocks (each block shares one sort per source chunk) and the packed keys
    must stay inside float32's exact integer range.
    """
    if out.dtype not in _SORT_DTYPES:
        return False
    ndim = index.dim()
    if ndim == 0 or dim != ndim - 1:
        return False
    if not (index.is_contiguous() and src.is_contiguous() and out.is_contiguous()):
        return False
    cols = index.shape[-1]
    if cols == 0:
        return True
    out_cols = out.shape[-1]
    if out_cols == 0:
        return True
    tile = min(_next_pow2(max(cols, out_cols)), _SORT_TILE)
    n_blocks = -(-out_cols // tile)
    n_chunks = -(-cols // tile)
    # ``t1`` reaches (n_blocks * tile - 1) * tile; keep it exact in fp32.
    if n_blocks * tile * tile > _FP32_EXACT:
        return False
    if n_blocks > _SORT_MAX_BLOCKS or n_chunks > _SORT_MAX_CHUNKS:
        return False
    rows = index.numel() // cols
    if rows == 0:
        return True
    _scatter_last_dim_sort_kernel[(min(rows, _MAX_GRID_X),)](
        src,
        index,
        out,
        rows,
        cols,
        src.shape[-1],
        out_cols,
        S=tile,
        LOGS=tile.bit_length() - 1,
        NBLK=n_blocks,
    )
    return True


def _scatter_last_dim(out, out_contiguous, dim, index, src) -> bool:
    """Try the specialised innermost-dim scatter; return True if it ran.

    ``dim`` must be the innermost dimension and ``index``/``src``/``out`` must
    be contiguous, so every row of each tensor is a flat run of ``stride(-2)``
    elements.  ``src`` may be wider than ``index`` (in any dimension); for
    ranks above two the leading shapes must agree exactly, otherwise a flat
    row index would not map onto the same coordinates in every tensor.
    """
    ndim = index.dim()
    if dim < 0:
        dim += ndim
    if ndim == 0 or dim != ndim - 1 or not out_contiguous:
        return False
    if index.dim() != out.dim() or index.dim() != src.dim():
        return False
    if not index.is_contiguous() or not src.is_contiguous():
        return False
    if ndim > 2:
        outer = index.shape[:-1]
        if out.shape[:-1] != outer or src.shape[:-1] != outer:
            return False
    elif ndim == 2:
        # torch guarantees index.size(0) <= src.size(0) / inp.size(0); be safe.
        if out.shape[0] < index.shape[0] or src.shape[0] < index.shape[0]:
            return False
    if index.numel() >= _INT32_LIMIT or out.numel() >= _INT32_LIMIT:
        return False
    if src.numel() >= _INT32_LIMIT:
        return False

    cols = index.shape[-1]
    if cols == 0:
        return True
    if _scatter_last_dim_sorted(out, dim, index, src):
        return True
    rows = index.numel() // cols
    block = min(max(_MIN_ROW_BLOCK, _next_pow2(cols)), _ROW_BLOCK)
    tiles_per_row = (cols + block - 1) // block
    n_tiles = rows * tiles_per_row
    if n_tiles == 0:
        return True
    grid = (min(n_tiles, _MAX_GRID_X),)
    _scatter_last_dim_kernel[grid](
        src,
        index,
        out,
        cols,
        out.shape[-1],
        src.shape[-1],
        tiles_per_row,
        n_tiles,
        BLOCK=block,
        EVEN=(cols % block == 0),
    )
    return True


